const VERTEX_SOURCE=`#version 300 es
in vec2 a_position;
void main(){gl_Position=vec4(a_position,0.0,1.0);}`;
function compile(gl,type,source){const shader=gl.createShader(type);gl.shaderSource(shader,source);gl.compileShader(shader);if(!gl.getShaderParameter(shader,gl.COMPILE_STATUS)){const error=gl.getShaderInfoLog(shader)||"Unknown shader compile error";gl.deleteShader(shader);throw new Error(error);}return shader;}
function link(gl,vertex,fragmentSource){const fragment=compile(gl,gl.FRAGMENT_SHADER,fragmentSource),program=gl.createProgram();gl.attachShader(program,vertex);gl.attachShader(program,fragment);gl.linkProgram(program);gl.deleteShader(fragment);if(!gl.getProgramParameter(program,gl.LINK_STATUS)){const error=gl.getProgramInfoLog(program)||"Unknown program link error";gl.deleteProgram(program);throw new Error(error);}return program;}
export function createRenderer(canvas,{onContextLost=()=>{},onContextRestored=()=>{}}={}){
 const options={antialias:false,alpha:false,preserveDrawingBuffer:true,powerPreference:"high-performance",desynchronized:true};let gl=canvas.getContext("webgl2",options);if(!gl)throw new Error("WebGL2 is required.");
 canvas.addEventListener("webglcontextlost",e=>{e.preventDefault();onContextLost();});canvas.addEventListener("webglcontextrestored",()=>onContextRestored());
 let vertex=compile(gl,gl.VERTEX_SHADER,VERTEX_SOURCE),buffer=gl.createBuffer(),current=null,settings={motion:1,intensity:1};gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);
 function setFragmentSource(source){const program=link(gl,vertex,source);if(current?.program)gl.deleteProgram(current.program);current={source,program,position:gl.getAttribLocation(program,"a_position"),resolution:gl.getUniformLocation(program,"u_resolution"),time:gl.getUniformLocation(program,"u_time"),motion:gl.getUniformLocation(program,"u_motion"),intensity:gl.getUniformLocation(program,"u_intensity")};}
 function resize(pixelRatio=Math.min(globalThis.devicePixelRatio||1,2)){const width=Math.max(1,Math.floor(canvas.clientWidth*pixelRatio||canvas.width||64)),height=Math.max(1,Math.floor(canvas.clientHeight*pixelRatio||canvas.height||64));if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;}gl.viewport(0,0,canvas.width,canvas.height);}
 function draw(timeSeconds,shouldResize=true){if(!current)return;if(shouldResize)resize();gl.useProgram(current.program);gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.enableVertexAttribArray(current.position);gl.vertexAttribPointer(current.position,2,gl.FLOAT,false,0,0);gl.uniform2f(current.resolution,canvas.width,canvas.height);gl.uniform1f(current.time,timeSeconds);if(current.motion)gl.uniform1f(current.motion,settings.motion);if(current.intensity)gl.uniform1f(current.intensity,settings.intensity);gl.drawArrays(gl.TRIANGLES,0,3);}
 function sample(timeSeconds,size=64,sampleSettings=settings){const oldW=canvas.width,oldH=canvas.height,old={...settings};settings={...settings,...sampleSettings};canvas.width=size;canvas.height=size;gl.viewport(0,0,size,size);draw(timeSeconds,false);const pixels=new Uint8Array(size*size*4);gl.readPixels(0,0,size,size,gl.RGBA,gl.UNSIGNED_BYTE,pixels);canvas.width=oldW;canvas.height=oldH;gl.viewport(0,0,oldW,oldH);settings=old;return pixels;}
 function sampleSequence(times=[.73,2.11,4.47],size=64,sampleSettings=settings){return times.map(t=>sample(t,size,sampleSettings));}
 function setSettings(next){settings={...settings,...next};}
 function destroy(){if(current?.program)gl.deleteProgram(current.program);if(vertex)gl.deleteShader(vertex);if(buffer)gl.deleteBuffer(buffer);}
 return{setFragmentSource,render:t=>draw(t,true),sample,sampleSequence,resize,setSettings,destroy,get source(){return current?.source||null;}};
}
